INSERT INTO `announcement` (`title`, `content`) VALUES
('失物招领平台正式上线', '亲爱的同学们，学校失物招领平台现已正式上线！通过本平台，你可以发布失物信息或者招领信息，帮助物品回到主人手中。请大家积极使用，共同营造温馨和谐的校园环境。'),
('关于规范使用失物招领平台的通知', '为了保证平台的有序运行，请大家在发布信息时注意以下几点：1. 信息要真实准确；2. 物品描述要详细；3. 联系方式要正确；4. 拾获贵重物品请及时交至保卫处。感谢大家的配合！'),
('失物招领平台使用指南', '同学们可以通过以下步骤使用平台：1. 注册/登录账号；2. 选择"我丢失了"或"我拾到了"；3. 填写物品信息和联系方式；4. 提交后等待审核；5. 审核通过后信息将被公开展示。如有问题请联系管理员。'),
('本周失物招领工作总结', '本周平台共发布失物信息32条，招领信息28条，成功匹配并归还物品15件。感谢大家的积极参与，让我们继续努力，让更多失物回到主人手中！'),
('寻找校园卡专项行动', '近期发现很多同学遗失了校园卡，为此我们启动"寻找校园卡"专项行动。如拾到校园卡，请及时上传至平台或交至学生服务中心。失主可通过平台查询或前往学生服务中心认领。'),
('系统维护通知', '为提升用户体验，系统将于本周六凌晨2:00-4:00进行维护升级，期间平台将暂停服务。给大家带来的不便敬请谅解。'),
('关于加强贵重物品保管的提醒', '近期笔记本电脑、手机等贵重物品遗失案例有所增加，请同学们加强个人财物保管意识，不要将贵重物品随意放置。如有遗失，请及时通过平台发布信息并联系保卫处。'),
('失物招领志愿者招募', '为更好地服务广大师生，现面向全校招募失物招领志愿者。志愿者将协助管理员审核信息、整理物品、联系失主等。有意者请联系学生会公益部。'),
('平台新功能上线通知', '平台新增"物品匹配"功能，系统将自动分析失物和招领信息，为可能匹配的物品发送提醒。请大家及时查看系统通知，提高认领效率。'),
('文明拾金不昧表彰公告', '本学期以来，共有32名同学在拾到贵重物品后及时上交或通过平台归还失主。学校将对这些同学进行表彰，名单详见学生处网站。感谢这些同学弘扬拾金不昧的优良传统！'),
('假期前失物招领工作安排', '临近假期，请有遗失物品的同学尽快前来认领。假期期间，失物招领平台将继续运行，但线下认领服务将调整为每周一、三、五上午开放。'),
('关于防范招领诈骗的提醒', '近期发现有不法分子冒充失主骗取招领物品的情况。请大家在归还物品时，核实对方身份，必要时可要求对方出示证件或详细描述物品特征。'),
('失物招领平台微信小程序上线', '为方便大家随时随地发布和查询失物招领信息，平台微信小程序现已上线。扫描校园公告栏二维码即可使用，欢迎大家下载体验。'),
('校园卡挂失与补办流程', '遗失校园卡的同学请及时挂失，可通过以下方式：1. 登录校园网自助挂失；2. 前往学生服务中心挂失；3. 拨打挂失热线。挂失后可持有效证件前往学生服务中心申请补办。'),
('期末考试期间临时失物招领点设置通知', '为方便同学们在考试期间及时找回遗失物品，学校将在各考场附近设置临时失物招领点，由志愿者值守。考试结束后遗留在考场的物品将被集中存放，请及时认领。');
